using System.IO;

namespace FullStackLauncher.Services;

public static partial class GitRepositoryService
{
    private static async Task<IReadOnlyList<string>> CloneFilterOptionsAsync(string folder, CancellationToken token)
    {
        // Git for Windows installs these LFS filters system-wide, even for repositories without LFS files.
        // Accept only the commands generated by Git LFS itself, never a caller-provided shell expression.
        var filters = await GitAsync(folder,
            ["config", "--null", "--get-regexp", "^filter\\..*\\.(clean|smudge|process)$"], token).ConfigureAwait(false);
        if (filters.ExitCode is not (0 or 1)) ThrowCommandFailure(filters);
        var lfsCommands = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var entry in filters.Output.Split('\0', StringSplitOptions.RemoveEmptyEntries))
        {
            var separator = entry.IndexOf('\n');
            if (separator <= 0) throw UnsupportedCloneFilter();
            var key = entry[..separator];
            var command = entry[(separator + 1)..];
            if (string.IsNullOrWhiteSpace(command))
            {
                // Preserve a later empty override instead of re-enabling an explicitly disabled LFS filter.
                if (key is "filter.lfs.clean" or "filter.lfs.smudge" or "filter.lfs.process") lfsCommands[key] = "";
                continue;
            }
            var supported = key switch
            {
                "filter.lfs.clean" => command == "git-lfs clean -- %f",
                "filter.lfs.smudge" => command is "git-lfs smudge -- %f" or "git-lfs smudge --skip -- %f",
                "filter.lfs.process" => command is "git-lfs filter-process" or "git-lfs filter-process --skip",
                _ => false
            };
            if (!supported) throw UnsupportedCloneFilter();
            lfsCommands[key] = command;
        }
        if (!lfsCommands.Values.Any(command => command.Length > 0)) return [];

        // Standard LFS can delegate to extension and transfer commands. Those remain outside guided cloning.
        var extensions = await GitAsync(folder,
            ["config", "--null", "--get-regexp",
                "^lfs\\.(customtransfer\\..*\\.(path|args)|extension\\..*\\.(clean|smudge))$"], token).ConfigureAwait(false);
        if (extensions.ExitCode is not (0 or 1)) ThrowCommandFailure(extensions);
        foreach (var entry in extensions.Output.Split('\0', StringSplitOptions.RemoveEmptyEntries))
        {
            var separator = entry.IndexOf('\n');
            if (separator <= 0 || !string.IsNullOrWhiteSpace(entry[(separator + 1)..]))
                throw new InvalidOperationException("Custom Git LFS extensions or transfer commands are configured. "
                    + "Clone with Git directly, then add the cloned folder.");
        }

        var executable = await ResolveCloneLfsExecutableAsync(folder, token).ConfigureAwait(false);
        // Git runs filters through its POSIX shell. Quote the exact installed executable; never resolve it from the checkout.
        var quoted = "'" + executable.Replace('\\', '/').Replace("'", "'\\''", StringComparison.Ordinal) + "'";
        var options = new List<string>();
        foreach (var (key, command) in lfsCommands)
            options.AddRange(["-c", key + "=" + (command.Length == 0 ? "" : quoted + command["git-lfs".Length..])]);
        return options;
    }

    private static async Task<string> ResolveCloneLfsExecutableAsync(string folder, CancellationToken token)
    {
        var lookup = await GitAsync(folder, ["--exec-path"], token).ConfigureAwait(false);
        if (lookup.ExitCode != 0) ThrowCommandFailure(lookup);
        var path = lookup.Output.TrimEnd('\r', '\n');
        if (string.IsNullOrWhiteSpace(path) || path != path.Trim() || path.Any(char.IsControl)
            || !Path.IsPathFullyQualified(path) || path.StartsWith("\\\\", StringComparison.Ordinal)
            || path.StartsWith("//", StringComparison.Ordinal)) throw CloneLfsUnavailable();
        try
        {
            var directory = Path.GetFullPath(path);
            var candidates = new List<string> { Path.Combine(directory, "git-lfs.exe") };
            var distribution = Directory.GetParent(directory)?.Parent?.FullName;
            if (distribution is not null) candidates.Add(Path.Combine(distribution, "bin", "git-lfs.exe"));
            foreach (var candidate in candidates.Distinct(StringComparer.OrdinalIgnoreCase))
            {
                token.ThrowIfCancellationRequested();
                if (!File.Exists(candidate)) continue;
                RequireUnlinkedCloneAncestry(Path.GetDirectoryName(candidate)!);
                if (new FileInfo(candidate).LinkTarget is null) return candidate;
            }
        }
        catch (Exception exception) when (exception is ArgumentException or NotSupportedException or IOException or UnauthorizedAccessException)
        { throw CloneLfsUnavailable(); }
        throw CloneLfsUnavailable();
    }

    private static InvalidOperationException UnsupportedCloneFilter() => new(
        "A custom Git filter is configured. Guided cloning supports standard Git LFS filters. "
        + "Clone with Git directly, then add the cloned folder.");

    private static InvalidOperationException CloneLfsUnavailable() => new(
        "Git LFS filters are configured, but git-lfs.exe was not found in this Git installation. "
        + "Install or update Git for Windows with Git LFS, then retry.");
}
